    "philosophy.title": "Filosof\u00eda",
    "philosophy.neutral_title": "Neutral",
    "philosophy.neutral_desc": "Sin dependencia de proveedor. Cualquier sistema puede producir o consumir eventos IAES sin dependencias propietarias.",
    "philosophy.event_title": "Orientado a Eventos",
    "philosophy.event_desc": "Los eventos son ciudadanos de primera clase. Cada evento es autocontenido, trazable e independientemente significativo.",
    "philosophy.intent_title": "Intenci\u00f3n, No Comando",
    "philosophy.intent_desc": "IAES declara qu\u00e9 deber\u00eda ocurrir, no c\u00f3mo. Los consumidores deciden la implementaci\u00f3n \u2014 preservando autonom\u00eda y flexibilidad.",
    "philosophy.open_title": "Est\u00e1ndar Abierto",
    "philosophy.open_desc": "Licenciado bajo CC BY 4.0. Libre de usar, implementar, extender y distribuir. Desarrollo abierto en GitHub.",
    "philosophy.compat_title": "Compatible hacia Atr\u00e1s",
