    "ecosystem.prod_ai": "Moteurs de diagnostic AI",
    "ecosystem.prod_rules": "Moteurs de r\u00e8gles",
    "ecosystem.prod_inspection": "Inspection manuelle",
    "ecosystem.prod_lab": "Analyse en laboratoire",
    "ecosystem.prod_temp": "Capteurs de temp\u00e9rature",
    "ecosystem.prod_acoustic": "Syst\u00e8mes acoustiques",
    "ecosystem.prod_edge": "Passerelles edge",
    "ecosystem.prod_cameras": "Cam\u00e9ras / vid\u00e9o",
    "ecosystem.consumers_title": "Consommateurs",
    "ecosystem.cons_timeseries": "Bases de donn\u00e9es de s\u00e9ries temporelles",
    "ecosystem.cons_twin": "Plateformes de Jumeau Num\u00e9rique",
    "philosophy.title": "Philosophie",
    "philosophy.neutral_title": "Neutre",
    "philosophy.neutral_desc": "Aucune d\u00e9pendance fournisseur. Tout syst\u00e8me peut produire ou consommer des \u00e9v\u00e9nements IAES sans d\u00e9pendances propri\u00e9taires.",
    "philosophy.event_title": "Orient\u00e9 \u00c9v\u00e9nements",
    "philosophy.event_desc": "Les \u00e9v\u00e9nements sont des citoyens de premi\u00e8re classe. Chaque \u00e9v\u00e9nement est autonome, tra\u00e7able et ind\u00e9pendamment significatif.",
    "philosophy.intent_title": "Intention, Pas Commande",
    "philosophy.intent_desc": "IAES d\u00e9clare ce qui devrait se passer, pas comment. Les consommateurs d\u00e9cident de l'impl\u00e9mentation \u2014 pr\u00e9servant autonomie et flexibilit\u00e9.",
    "philosophy.open_title": "Standard Ouvert",
    "philosophy.open_desc": "Licenci\u00e9 sous CC BY 4.0. Libre d'utilisation, d'impl\u00e9mentation, d'extension et de distribution. D\u00e9veloppement ouvert sur GitHub.",
    "philosophy.compat_title": "R\u00e9trocompatible",
    "philosophy.compat_desc": "Les nouvelles versions ajoutent des champs optionnels. Les producteurs et consommateurs existants continuent de fonctionner sans modification.",
    "opensource.title": "Open Source",
    "opensource.desc": "IAES est d\u00e9velopp\u00e9 ouvertement. La sp\u00e9cification, les sch\u00e9mas JSON, les exemples et les impl\u00e9mentations de r\u00e9f\u00e9rence sont disponibles sur GitHub. Contributions, issues et discussions sont les bienvenues.",
    "opensource.cta_repo": "Voir sur GitHub",
    "opensource.cta_star": "Donner une \u00c9toile",
    "opensource.license": "Licenci\u00e9 sous Creative Commons Attribution 4.0 (CC BY 4.0)",
