    "events.sensor_title": "\uc13c\uc11c \uc218\uba85 \uc8fc\uae30",
    "events.sensor_desc": "\uc790\uc0b0 \ud50c\ub9bf \uc804\ubc18\uc5d0 \uac78\uccd0 \uc13c\uc11c\uc758 \ubc1c\uacac, \ub4f1\ub85d, \uad50\uc815 \ubc0f \ud574\uc81c\ub97c \ucd94\uc801\ud569\ub2c8\ub2e4.",
    "events.spare_title": "\ubd80\ud488 \uc18c\ube44",
    "events.spare_desc": "\uc720\uc9c0\ubcf4\uc218 \uc911 \uc18c\ube44\ub41c \uc608\ube44 \ubd80\ud488\uc744 \uae30\ub85d\ud569\ub2c8\ub2e4. \ube44\uc6a9 \ucd94\uc801 \ubc0f \uc7ac\uace0 \uacc4\ud68d\uc744 \uc704\ud574 \uc791\uc5c5 \uc9c0\uc2dc\uc11c\uc5d0 \uc5f0\uacb0\ub429\ub2c8\ub2e4.",
