    "philosophy.neutral_desc": "\ubca4\ub354 \uc885\uc18d \uc5c6\uc74c. \ubaa8\ub4e0 \uc2dc\uc2a4\ud15c\uc774 \ub3c5\uc810 \uc885\uc18d\uc131 \uc5c6\uc774 IAES \uc774\ubca4\ud2b8\ub97c \uc0dd\uc131\ud558\uac70\ub098 \uc18c\ube44\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",
    "philosophy.event_title": "\uc774\ubca4\ud2b8 \uc911\uc2ec",
    "philosophy.event_desc": "\uc774\ubca4\ud2b8\ub294 \uc77c\ub4f1 \uc2dc\ubbfc\uc785\ub2c8\ub2e4. \uac01 \uc774\ubca4\ud2b8\ub294 \uc790\uccb4 \ud3ec\ud568\ub418\uace0, \ucd94\uc801 \uac00\ub2a5\ud558\uba70, \ub3c5\ub9bd\uc801\uc73c\ub85c \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.",
    "philosophy.intent_title": "\uc758\ub3c4, \uba85\ub839\uc774 \uc544\ub2d8",
    "philosophy.intent_desc": "IAES\ub294 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub098\uc57c \ud558\ub294\uc9c0\ub97c \uc120\uc5b8\ud558\uc9c0, \uc5b4\ub5bb\uac8c\ub97c \uc120\uc5b8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc18c\ube44\uc790\uac00 \uad6c\ud604\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4 \u2014 \uc790\uc728\uc131\uacfc \uc720\uc5f0\uc131\uc744 \ubcf4\uc874\ud569\ub2c8\ub2e4.",
    "philosophy.open_title": "\uac1c\ubc29\ud615 \ud45c\uc900",
    "philosophy.open_desc": "CC BY 4.0\uc73c\ub85c \ub77c\uc774\uc120\uc2a4. \uc0ac\uc6a9, \uad6c\ud604, \ud655\uc7a5 \ubc0f \ubc30\ud3ec \uc790\uc720. GitHub\uc5d0\uc11c \uac1c\ubc29 \uac1c\ubc1c.",
    "philosophy.compat_title": "\ud558\uc704 \ud638\ud658",
    "philosophy.compat_desc": "\uc0c8 \ubc84\uc804\uc740 \uc120\ud0dd\uc801 \ud544\ub4dc\ub97c \ucd94\uac00\ud569\ub2c8\ub2e4. \uae30\uc874 \uc0dd\uc0b0\uc790\uc640 \uc18c\ube44\uc790\ub294 \ubcc0\uacbd \uc5c6\uc774 \uacc4\uc18d \uc791\ub3d9\ud569\ub2c8\ub2e4.",
    "opensource.title": "\uc624\ud508 \uc18c\uc2a4",
