    // Philosophy
    "philosophy.title": "Философия",
    "philosophy.neutral_title": "Вендор-нейтральный",
    "philosophy.neutral_desc": "Без привязки к вендору. Любая система может производить или потреблять события IAES без проприетарных зависимостей.",
    "philosophy.event_title": "Событийно-ориентированный",
    "philosophy.event_desc": "События — главные сущности. Каждое событие самодостаточно, прослеживаемо и независимо значимо.",
    "philosophy.intent_title": "Намерение, а не команда",
