    // Hero
    "hero.badge": "开放规范 v1.3",
    "hero.title": "工业资产<br>事件标准",
    "hero.subtitle": "一种最小化、供应商中立的工业资产事件语言。IAES 命名设备上发生的事情——测量、诊断、故障、维护操作——使任何系统都能在无需自定义集成的情况下生产、路由和消费资产事件。",
    "hero.cta_spec": "阅读规范",
    "hero.cta_install": "安装 SDK",
    "hero.cta_github": "GitHub",
    "hero.attribution": "开放标准。供应商中立。Wertek AI 参考实现。",
    // Problem
    "problem.title": "工业系统无法共享资产事件",
    "problem.subtitle": "在每个工业工厂中，关键系统都在孤立运行。每个系统都生成关于相同资产的事件——但格式、API 和语义完全不同。",
    "problem.each_formats": "不同的格式",
    "problem.each_apis": "不同的 API",
    "problem.each_semantics": "不同的语义",
    "problem.each_semantics_desc": "\"报警\" ≠ \"警报\" ≠ \"事件\" ≠ \"通知\"",
    "problem.iq_scada": "PLC 标签中的寄存器变化。没有上下文，没有资产标识，没有严重性模型。",
    "problem.iq_sap": "在事务系统中关闭的工单。不同的模式，不同的生命周期。",
    "problem.iq_ai": "带有置信度分数、RUL 和建议操作的概率诊断。与两者都不兼容。",
    "problem.result_title": "相同的资产。相同的事件。三种不兼容的表示。",
    "problem.result_desc": "工业中不存在资产事件的通用语言。IAES 提供了一种。",
    // Architecture
    "arch.title": "架构",
    "arch.subtitle": "边缘系统和智能层生成 IAES 事件。任何应用程序都可以消费它们。",
    "arch.bus_desc": "标准化事件信封——供应商中立、自描述、可追溯",
    "arch.src_human": "人员 / 应用",
    // How It Works
    "how.title": "工作原理",
    "how.subtitle": "PLC 和传感器不知道 IAES 的存在。智能层——AI 模型、规则引擎、网关——将原始信号转换为标准化事件。",
    "how.step1_title": "边缘系统检测到状态",
    "how.step1_desc": "振动传感器在压缩机 C-12 上读取 12.4 mm/s。能量计检测到功率因数降至 0.87。热像仪在轴承座上检测到 94°C。",
    "how.step2_title": "智能层生成 IAES 事件",
    "how.step2_desc": "AI 模型、规则引擎或网关解释原始数据，并发出包含资产标识、严重性和建议操作的标准化 IAES 事件。",
    "how.step3_title": "事件被任何系统消费",
    "how.step3_desc": "同一事件可以同时在 SAP 中创建工单、在 Grafana 中触发警报、更新数字孪生，并为 AI 模型提供趋势分析数据。",
    "how.key_insight": "核心洞察",
    "how.key_insight_desc": "PLC 不知道 IAES 的存在。AI 引擎读取原始振动数据并发出 IAES 事件。技术人员打开应用程序，记录诊断——这也是一个 IAES 事件。IAES 是智能层的语言——无论智能是人工的还是人类的。",
    // Ontology
    "ontology.title": "工业资产事件语言",
    "ontology.subtitle": "IAES 不仅仅是集成格式。它是一种事件本体——一种通用词汇表，命名工业资产上发生的一切。",
    "ontology.condition": "状态监测",
    "ontology.energy": "能源与电能质量",
    "ontology.maintenance": "维护与生命周期",
    "ontology.note": "每个事件名称都遵循相同的模式：<code>域.主体.状态</code>。一种任何系统都能生产、任何系统都能消费的通用词汇表。",
    // Definition
    "definition.title": "什么是 IAES",
    "definition.is_1": "事件语言——命名资产上发生的事情",
    "definition.is_2": "JSON 模式——最小化、自描述、机器可读",
    "definition.is_3": "传输无关——支持 MQTT、REST、OPC UA、Kafka、文件",
    "definition.is_4": "跨领域——振动、能源、维护、诊断、遥测",
    "definition.is_5": "事件驱动——每个事件独立、可追溯、有意义",
    "definition.is_6": "开放——CC BY 4.0，无供应商锁定，自由实施",
    "definition.not_1": "不是协议——IAES 不定义字节如何在线路上传输",
    "definition.not_2": "不是历史数据库——IAES 不存储或查询时间序列数据",
    "definition.not_3": "不是 CMMS——IAES 不管理工单或计划",
    "definition.not_4": "不是数字孪生框架——IAES 不建模资产结构",
    "definition.not_5": "不是数据模型——IAES 描述运动中的事件，而非静态数据",
    "definition.not_6": "不限于制造业——适用于能源、油气、采矿、公用事业、建筑",
    "definition.oneliner": "IAES 就是工业资产的事件语言。",
    // Comparison
    "compare.title": "IAES 与其他标准的关系",
    "compare.subtitle": "IAES 是现有工业标准的补充。它不取代它们——它提供连接它们的事件线格式。",
    "compare.col_standard": "标准",
    "compare.col_scope": "定义内容",
    "compare.col_iaes": "IAES 的不同之处",
    "compare.col_relationship": "关系",
    "compare.complement": "互补",
    "compare.different_layer": "不同层",
    "compare.iso55000_scope": "整个资产生命周期的管理框架——战略、规划、采购、运营、处置。",
    "compare.iso55000_iaes": "IAES 是在 ISO 55000 管理系统内传输运营数据的事件线格式。ISO 55000 说明<em>管理什么</em>；IAES 说明<em>事件如何流动</em>。",
    "compare.aas_scope": "数字孪生结构——定义外壳、子模型和 REST 接口，用于数字化表示资产。",
    "compare.aas_iaes": "AAS 定义数字孪生的<em>结构</em>。IAES 定义<em>流经其中的事件</em>。AAS 子模型可以生产或消费 IAES 事件。",
    "compare.cim_scope": "电力系统的信息模型——定义静态数据（拓扑、设备、测量）。",
    "compare.cim_iaes": "CIM 建模<em>静态</em>数据。IAES 建模<em>动态</em>数据——资产上发生的事件。CIM 告诉你什么存在；IAES 告诉你发生了什么。",
    "compare.ido_scope": "工业数据的语义本体——支持自动推理和知识图谱。",
    "compare.ido_iaes": "IDO 用于<em>语义推理</em>（RDF、OWL）。IAES 用于<em>运营事件路由</em>（JSON、MQTT、REST）。不同的技术栈层。",
    "compare.opcua_scope": "工业自动化通信协议——定义设备级别的机器通信方式。",
    "compare.opcua_iaes": "OPC UA 是<em>传输协议</em>（设备到设备）。IAES 是<em>事件模式</em>（系统到系统）。IAES 事件可以通过 OPC UA、MQTT、REST 或任何协议传输。",
    "compare.isa95_scope": "定义企业（ERP）与控制系统（SCADA/MES）之间的集成层级。",
    "compare.isa95_iaes": "ISA-95 定义<em>集成架构</em>（0-4 级）。IAES 为 2-4 级提供<em>事件合约</em>——跨越这些边界的实际数据格式。",
    "compare.summary_title": "IAES 填补了特定空白",
    "compare.summary_desc": "现有标准定义了如何管理资产（ISO 55000）、数字建模（AAS）、推理分析（IDO）或在设备间传输数据（OPC UA）。但没有一个标准定义资产事件的标准格式——测量、诊断、维护意图和完成。这正是 IAES 所做的。",
