    "ecosystem.prod_inspection": "Inspekcja ręczna",
    "ecosystem.prod_lab": "Analiza laboratoryjna",
    "ecosystem.prod_temp": "Czujniki temperatury",
    "ecosystem.prod_acoustic": "Systemy akustyczne",
    "ecosystem.prod_edge": "Bramki brzegowe",
    "ecosystem.prod_cameras": "Kamery / wideo",
    "ecosystem.consumers_title": "Konsumenci",
    "ecosystem.cons_timeseries": "Bazy danych szeregów czasowych",
    "ecosystem.cons_twin": "Platformy cyfrowych bliźniaków",
    // Philosophy
    "philosophy.title": "Filozofia",
    "philosophy.neutral_title": "Neutralny wobec dostawców",
    "philosophy.neutral_desc": "Bez uzależnienia od dostawcy. Każdy system może produkować lub konsumować zdarzenia IAES bez zastrzeżonych zależności.",
    "philosophy.event_title": "Zorientowany na zdarzenia",
    "philosophy.event_desc": "Zdarzenia są obywatelami pierwszej klasy. Każde zdarzenie jest samowystarczalne, identyfikowalne i niezależnie znaczące.",
    "philosophy.intent_title": "Zamiar, nie rozkaz",
    "philosophy.intent_desc": "IAES deklaruje, co powinno się wydarzyć, nie jak. Konsumenci decydują o implementacji — zachowując autonomię i elastyczność.",
    "philosophy.open_title": "Otwarty standard",
    "philosophy.open_desc": "Licencjonowany na CC BY 4.0. Wolny do użycia, implementacji, rozszerzenia i dystrybucji. Otwarte rozwijanie na GitHub.",
    "philosophy.compat_title": "Wstecznie kompatybilny",
    "philosophy.compat_desc": "Nowe wersje dodają opcjonalne pola. Istniejący producenci i konsumenci kontynuują pracę bez zmian.",
